 private static void loadOrSeed()throws IOException{load("venues.json",venues);Set<String> sampleVenueIds=new HashSet<>();for(Map<String,Object> v:venues)if("DEMO_OWNER_LISTING".equals(v.get("dataLabel")))sampleVenueIds.add(String.valueOf(v.get("id")));venues.removeIf(v->"DEMO_OWNER_LISTING".equals(v.get("dataLabel")));load("events.json",events);load("bookings.json",bookings);bookings.removeIf(b->sampleVenueIds.contains(String.valueOf(b.get("venueId"))));load("users.json",users);ensureAdmin();if(events.isEmpty())seedEvents();rebuildVenueSearchIndex();for(Map<String,Object> event:events){try{eventDuplicateIndex.addExisting(String.valueOf(event.get("title")),String.valueOf(event.get("locality")),LocalDate.parse(String.valueOf(event.get("startDatetime")).substring(0,10)).toString());}catch(Exception ignored){}}saveAll();}
