 private static void handle(HttpExchange x)throws IOException{try{if(x.getRequestMethod().equals("OPTIONS")){send(x,204,null);return;}String path=x.getRequestURI().getPath(),method=x.getRequestMethod();Map<String,String>q=query(x.getRequestURI());String body=new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);String auth=x.getRequestHeaders().getFirst("Authorization");Map<String,Object> actor=auth!=null&&auth.startsWith("Bearer ")?sessions.get(auth.substring(7)):null;Object result=route(method,path,q,body,actor);send(x,200,result);}catch(AuthException e){send(x,e.status,map("error",e.getMessage()));}catch(IllegalArgumentException e){send(x,400,map("error",e.getMessage()));}catch(IllegalStateException e){send(x,503,map("error",e.getMessage()));}catch(DateTimeException e){send(x,400,map("error","Invalid date/time: "+e.getMessage()));}catch(Exception e){e.printStackTrace();send(x,500,map("error","Server error","detail",e.getMessage()));}}
 private static final class AuthException extends RuntimeException { final int status; AuthException(int status,String message){super(message);this.status=status;} }
 private static Object route(String method,String path,Map<String,String>q,String body,Map<String,Object> actor) throws Exception{
  if(path.equals("/api/auth/register")&&method.equals("POST"))return register(Json.object(body));
  if(path.equals("/api/auth/login")&&method.equals("POST"))return login(Json.object(body));
  if(path.equals("/api/auth/me")&&method.equals("GET")){if(actor==null)throw new AuthException(401,"Please sign in.");return publicUser(actor);}
  if(path.equals("/api/auth/logout")&&method.equals("POST")){if(actor!=null)sessions.entrySet().removeIf(e->e.getValue()==actor);return map("success",true);}
  if(path.startsWith("/api/admin/")||path.equals("/api/admin/allocate")){requireRole(actor,"ADMIN");}
  if(path.equals("/api/bookings")&&method.equals("POST")||path.equals("/api/bookings/my")||path.startsWith("/api/bookings/")&&method.equals("PATCH")){requireRole(actor,"CUSTOMER","OWNER","ADMIN");}
  if(path.equals("/api/events")&&method.equals("POST")){requireRole(actor,"OWNER");}
  if(path.equals("/api/venues")&&method.equals("POST")){requireRole(actor,"OWNER");}

  if(path.equals("/api/discovery/places")&&method.equals("GET"))return OverpassService.search(q.getOrDefault("query","Mumbai"));
  if(path.equals("/api/health"))return map("status","ok","backend","Core Java HttpServer","algorithms",List.of("Trie","Binary Max Heap","Segment Tree","Bipartite Matching","Greedy Set Cover","Bloom Filter (CO5)"));
  if(path.equals("/api/venues/mine")&&method.equals("GET")){requireRole(actor,"OWNER");return venues.stream().filter(v->String.valueOf(actor.get("id")).equals(v.get("ownerId"))).toList();}
  if(path.equals("/api/venues")&&method.equals("GET")){return venues.stream().filter(v->"APPROVED".equals(v.get("status"))).filter(v->q.get("locality")==null||q.get("locality").equalsIgnoreCase(String.valueOf(v.get("locality")))||q.get("locality").equalsIgnoreCase("Mumbai")).filter(v->q.get("category")==null||q.get("category").equalsIgnoreCase(String.valueOf(v.get("category")))).toList();}
  if(path.equals("/api/venues")&&method.equals("POST"))return createVenue(Json.object(body),actor);
  if(path.equals("/api/admin/venues/pending"))return venues.stream().filter(v->"PENDING".equals(v.get("status"))).toList();
  if(path.startsWith("/api/admin/venues/")&&method.equals("PATCH")){String[]p=path.substring("/api/admin/venues/".length()).split("/");if(p.length==2){Map<String,Object>v=findVenue(p[0]);v.put("status",p[1].equals("approve")?"APPROVED":"REJECTED");saveAll();return v;}}
  if(path.equals("/api/recommendations")&&method.equals("POST"))return recommend(Json.object(body));
  if(path.equals("/api/search/suggest")){String prefix=q.getOrDefault("q","");return map("suggestions",venueSearchIndex.suggest(List.of(),prefix,8));}
  if(path.equals("/api/bookings/my")&&method.equals("GET")){String uid=String.valueOf(actor.get("id"));return bookings.stream().filter(b->uid.equals(b.get("customerId"))||("OWNER".equals(actor.get("role"))&&venues.stream().anyMatch(v->String.valueOf(v.get("id")).equals(b.get("venueId"))&&uid.equals(v.get("ownerId"))))||"ADMIN".equals(actor.get("role"))).toList();}
  if(path.equals("/api/bookings")&&method.equals("POST")){Map<String,Object> in=Json.object(body);in.put("customerId",actor.get("id"));in.put("customerName",actor.get("name"));return createBooking(in);}
  if(path.equals("/api/events")&&method.equals("POST"))return createEvent(Json.object(body),actor);
  if(path.equals("/api/events")&&method.equals("GET"))return events.stream().filter(e->q.get("locality")==null||q.get("locality").equals(e.get("locality"))).filter(e->q.get("status")==null||q.get("status").equals(e.get("status"))).toList();
  if(path.equals("/api/admin/allocate")&&method.equals("POST"))return allocate(Json.object(body));
  if(path.equals("/api/recommendations/cover")&&method.equals("POST"))return cover(Json.object(body));
  if(path.startsWith("/api/venues/")){String rest=path.substring("/api/venues/".length());String[]p=rest.split("/");Map<String,Object>v=findVenue(p[0]);if(p.length==1&&method.equals("GET"))return v;if(p.length==2&&p[1].equals("availability"))return availability(v,q);if(p.length==2&&p[1].equals("nearby-events"))return events.stream().filter(e->distance(num(v,"lat"),num(v,"lng"),num(e,"lat"),num(e,"lng"))<4).toList();}
  if(path.startsWith("/api/bookings/")&&method.equals("PATCH")){String[]p=path.substring(14).split("/");if(p.length==2){Map<String,Object> booking=bookings.stream().filter(b->p[0].equals(b.get("id"))).findFirst().orElseThrow(()->new IllegalArgumentException("Booking not found"));String role=String.valueOf(actor.get("role")),uid=String.valueOf(actor.get("id"));boolean owner=venues.stream().anyMatch(v->String.valueOf(v.get("id")).equals(booking.get("venueId"))&&uid.equals(v.get("ownerId")));boolean customer=uid.equals(booking.get("customerId"));if(!(role.equals("ADMIN")||(role.equals("OWNER")&&owner)||(role.equals("CUSTOMER")&&customer&&p[1].equals("cancel"))))throw new AuthException(403,"You do not have permission to update this booking.");if(role.equals("OWNER")&&(!List.of("approve","reject").contains(p[1])||!"REQUESTED".equals(booking.get("status"))))throw new IllegalArgumentException("Owners can approve or reject only pending booking requests.");if(role.equals("CUSTOMER")&&(!List.of("REQUESTED","APPROVED").contains(booking.get("status"))||Instant.parse(String.valueOf(booking.get("start"))).isBefore(Instant.now())))throw new IllegalArgumentException("This booking can no longer be cancelled.");return updateBooking(p[0],p[1]);}}
  throw new IllegalArgumentException("Unknown API route: "+method+" "+path);
 }
 private static void ensureAdmin(){if(users.stream().noneMatch(u->"ADMIN".equals(u.get("role")))){String email=System.getenv().getOrDefault("DROP_ADMIN_EMAIL","admin@drop.local").toLowerCase(Locale.ROOT);String pass=System.getenv().getOrDefault("DROP_ADMIN_PASSWORD","DropAdmin!2026");users.add(map("id","admin-1","name","DROP Administrator","email",email,"role","ADMIN","salt",UUID.randomUUID().toString(),"passwordHash",""));Map<String,Object> a=users.get(users.size()-1);a.put("passwordHash",hash(pass,String.valueOf(a.get("salt"))));save("users.json",users);}}
 private static Map<String,Object> register(Map<String,Object> in){String name=String.valueOf(in.getOrDefault("name","")).trim(),email=String.valueOf(in.getOrDefault("email","")).trim().toLowerCase(Locale.ROOT),password=String.valueOf(in.getOrDefault("password","")),role=String.valueOf(in.getOrDefault("role","CUSTOMER")).toUpperCase(Locale.ROOT);if(name.isBlank()||!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")||password.length()<8)throw new IllegalArgumentException("Enter a name, valid email and password of at least 8 characters.");if(!List.of("CUSTOMER","OWNER").contains(role))throw new IllegalArgumentException("Choose Customer or Venue Owner.");if(users.stream().anyMatch(u->email.equals(u.get("email"))))throw new IllegalArgumentException("An account with this email already exists.");String salt=UUID.randomUUID().toString();Map<String,Object>u=map("id","u-"+UUID.randomUUID(),"name",name,"email",email,"role",role,"salt",salt,"passwordHash",hash(password,salt));users.add(u);save("users.json",users);return createSession(u);}
 private static Map<String,Object> login(Map<String,Object> in){String email=String.valueOf(in.getOrDefault("email","")).toLowerCase(Locale.ROOT),password=String.valueOf(in.getOrDefault("password",""));Map<String,Object>u=users.stream().filter(x->email.equals(x.get("email"))).findFirst().orElse(null);if(u==null||!constantEquals(String.valueOf(u.get("passwordHash")),hash(password,String.valueOf(u.get("salt")))))throw new IllegalArgumentException("Email or password is incorrect.");return createSession(u);}
 private static Map<String,Object> createSession(Map<String,Object>u){String token=UUID.randomUUID().toString()+UUID.randomUUID().toString().replace("-","");sessions.put(token,u);return map("token",token,"user",publicUser(u));}
 private static Map<String,Object> publicUser(Map<String,Object>u){return map("id",u.get("id"),"name",u.get("name"),"email",u.get("email"),"role",u.get("role"));}
 private static void requireRole(Map<String,Object>u,String... roles){if(u==null)throw new AuthException(401,"Please sign in to continue.");for(String role:roles)if(role.equals(u.get("role")))return;throw new AuthException(403,"Your account does not have permission for this action.");}
 private static String hash(String password,String salt){try{PBEKeySpec spec=new PBEKeySpec(password.toCharArray(),salt.getBytes(StandardCharsets.UTF_8),120000,256);byte[] b=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();return Base64.getEncoder().encodeToString(b);}catch(Exception e){throw new IllegalStateException("Password hashing is unavailable.");}}
 private static boolean constantEquals(String a,String b){return java.security.MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}
 private static synchronized Map<String,Object> createVenue(Map<String,Object> in,Map<String,Object> actor){
  String name=String.valueOf(in.getOrDefault("name","")).trim(), locality=String.valueOf(in.getOrDefault("locality","")).trim();
  if(name.length()<3||locality.isBlank())throw new IllegalArgumentException("Enter a venue name and locality.");
  int capacity=in.get("capacity") instanceof Number n?n.intValue():0, area=in.get("areaSqft") instanceof Number n?n.intValue():0, hourly=in.get("hourlyRate") instanceof Number n?n.intValue():0;
  if(capacity<1||area<1||hourly<1)throw new IllegalArgumentException("Capacity, area and hourly price must be positive.");
  List<String> amenities=in.get("amenities") instanceof List<?> a?a.stream().map(String::valueOf).toList():List.of();
  double lat=in.get("lat") instanceof Number n?n.doubleValue():19.0760, lng=in.get("lng") instanceof Number n?n.doubleValue():72.8777;
  String phone=String.valueOf(in.getOrDefault("contactPhone","")).trim();
  Map<String,Object> v=map("id","venue-"+UUID.randomUUID(),"name",name,"category",in.getOrDefault("category","Pop-up"),"locality",locality,"unitLabel",in.getOrDefault("unitLabel","Event space"),"areaSqft",area,"capacity",capacity,"lat",lat,"lng",lng,"pricing",map("HOUR",hourly,"HALF_DAY",hourly*4,"DAY",hourly*7,"WEEK",hourly*38),"rating",0,"reviewCount",0,"images",List.of(String.valueOf(in.getOrDefault("imageUrl","https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1200&q=70"))),"description",in.getOrDefault("description","New owner-submitted venue. Details subject to admin verification."),"amenities",amenities,"rules",map("noise","Confirm with owner","alcohol","Subject to owner approval","food","Confirm with owner","decor","Confirm with owner"),"ownerId",actor.get("id"),"ownerEmail",actor.get("email"),"contactPhone",phone,"status","PENDING","dataLabel","OWNER_SUBMITTED");
  venues.add(0,v);rebuildVenueSearchIndex();saveAll();return v;
 }
 private static Map<String,Object> findVenue(String id){return venues.stream().filter(v->id.equals(v.get("id"))).findFirst().orElseThrow(()->new IllegalArgumentException("Venue not found"));}
 private static List<Map<String,Object>> recommend(Map<String,Object>q){List<Map<String,Object>> eligible=new ArrayList<>();for(var v:venues){if(!"APPROVED".equals(v.get("status")))continue;if(q.get("locality")!=null&&!q.get("locality").equals(v.get("locality")))continue;if(q.get("category")!=null&&!q.get("category").equals(v.get("category")))continue;if(q.get("guests") instanceof Number n&&num(v,"capacity")<n.intValue())continue;eligible.add(v);}MaxHeap<Map<String,Object>> heap=new MaxHeap<>();for(var v:eligible){double score=score(v,q);Map<String,Object> copy=new LinkedHashMap<>(v);copy.put("score",Math.round(score));copy.put("scoreBreakdown",map("category",q.get("category")==null||q.get("category").equals(v.get("category"))?100:30,"location",q.get("locality")==null?70:100,"capacity",q.get("guests")==null?70:Math.max(50,100-(num(v,"capacity")-((Number)q.get("guests")).intValue())),"budget",q.get("budget")==null?70:(num((Map<?,?>)v.get("pricing"),"HOUR")<=((Number)q.get("budget")).doubleValue()?100:40),"facilities",Math.min(100,((List<?>)v.get("amenities")).size()*11),"quality",(int)(num(v,"rating")/5*100),"eventDemand",70));heap.add(score,copy);}List<Map<String,Object>>out=new ArrayList<>();while(!heap.isEmpty())out.add(heap.poll().value());return out;}
 private static double score(Map<String,Object>v,Map<String,Object>q){double cat=q.get("category")==null||q.get("category").equals(v.get("category"))?100:30,loc=q.get("locality")==null||q.get("locality").equals(v.get("locality"))?100:40,cap=q.get("guests") instanceof Number n?Math.max(0,100-Math.max(0,num(v,"capacity")-n.intValue())):70,bud=70;if(q.get("budget") instanceof Number b){double price=num((Map<?,?>)v.get("pricing"),"HOUR");bud=price<=b.doubleValue()?100:Math.max(0,100-(price-b.doubleValue())/b.doubleValue()*100);}double facilities=Math.min(100,((List<?>)v.get("amenities")).size()*11),quality=num(v,"rating")/5*100;return cat*.22+loc*.20+cap*.15+bud*.15+facilities*.08+quality*.10+70*.10;}
 private static Object availability(Map<String,Object>v,Map<String,String>q){LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));String from=q.getOrDefault("from",today.toString()),to=q.getOrDefault("to",today.plusDays(14).toString());List<Object>out=new ArrayList<>();LocalDate a=LocalDate.parse(from),b=LocalDate.parse(to);if(b.isBefore(a)||b.toEpochDay()-a.toEpochDay()>90)throw new IllegalArgumentException("Choose a date range of at most 90 days.");for(LocalDate d=a;!d.isAfter(b);d=d.plusDays(1)){String dateKey=d.toString();SegmentTree tree=treeFor(String.valueOf(v.get("id")),d);int freeSlots=tree.query(0,47);out.add(map("date",dateKey,"state",freeSlots==48?"FREE":freeSlots==0?"BOOKED":"BLOCKED"));}return out;}
 private static synchronized Map<String,Object> createBooking(Map<String,Object>in){Map<String,Object>v=findVenue(String.valueOf(in.get("venueId")));if(!"APPROVED".equals(v.get("status"))||!"OWNER_SUBMITTED".equals(v.get("dataLabel")))throw new IllegalArgumentException("This listing is not an owner-verified, bookable DROP venue.");int guests=in.get("guests") instanceof Number gn?gn.intValue():1;if(guests<1||guests>num(v,"capacity"))throw new IllegalArgumentException("Guest count must be between 1 and the venue capacity.");String start=String.valueOf(in.get("start")),end=String.valueOf(in.get("end"));Instant startInstant=Instant.parse(start),endInstant=Instant.parse(end);if(!endInstant.isAfter(startInstant))throw new IllegalArgumentException("End time must be after start time");ZonedDateTime st=startInstant.atZone(ZoneId.of("Asia/Kolkata")),en=endInstant.atZone(ZoneId.of("Asia/Kolkata"));LocalDate day=st.toLocalDate();if(!en.toLocalDate().equals(day))throw new IllegalArgumentException("A booking must start and end on the same calendar day in this prototype.");if(startInstant.isBefore(Instant.now()))throw new IllegalArgumentException("Bookings must start in the future.");if(st.getSecond()!=0||st.getNano()!=0||en.getSecond()!=0||en.getNano()!=0)throw new IllegalArgumentException("Booking times must use whole minutes.");if(st.getHour()<6||en.getHour()>23||en.getHour()==23&&en.getMinute()>30)throw new IllegalArgumentException("Bookings must be between 06:00 and 23:30 Mumbai time.");int first=st.getHour()*2+st.getMinute()/30,last=(int)Math.ceil(en.toLocalTime().toSecondOfDay()/1800.0)-1;if(last-first<1)throw new IllegalArgumentException("Bookings must be at least one hour long.");SegmentTree availability=treeFor(String.valueOf(v.get("id")),day);if(availability.query(first,last)!=(last-first+1))throw new IllegalArgumentException("Requested time slots are not available.");double hours=(endInstant.toEpochMilli()-startInstant.toEpochMilli())/3600000.0;double subtotal=num((Map<?,?>)v.get("pricing"),"HOUR")*hours,fee=Math.round(subtotal*.08);Map<String,Object>b=map("id","b"+UUID.randomUUID(),"venueId",v.get("id"),"venueName",v.get("name"),"venueImage",((List<?>)v.get("images")).get(0),"locality",v.get("locality"),"start",start,"end",end,"purpose",in.getOrDefault("purpose","Pop-up"),"guests",guests,"subtotal",Math.round(subtotal),"fee",fee,"total",Math.round(subtotal)+fee,"status","REQUESTED","customerId",in.get("customerId"),"customerName",in.getOrDefault("customerName","DROP Customer"),"createdAt",Instant.now().toString());bookings.add(0,b);for(int slot=first;slot<=last;slot++)availability.update(slot,0);saveAll();return b;}
 private static SegmentTree treeFor(String venueId,LocalDate day){String cacheKey=venueId+"|"+day;SegmentTree cached=calendars.get(cacheKey);if(cached!=null)return cached;int[]slots=new int[48];Arrays.fill(slots,1);for(Map<String,Object>b:bookings){if(!venueId.equals(b.get("venueId"))||!List.of("REQUESTED","APPROVED").contains(b.get("status")))continue;try{ZonedDateTime st=Instant.parse(String.valueOf(b.get("start"))).atZone(ZoneId.of("Asia/Kolkata")),en=Instant.parse(String.valueOf(b.get("end"))).atZone(ZoneId.of("Asia/Kolkata"));if(!st.toLocalDate().equals(day))continue;int a=st.getHour()*2+st.getMinute()/30,z=Math.min(47,(int)Math.ceil((en.toLocalTime().toSecondOfDay())/1800.0)-1);for(int i=Math.max(0,a);i<=z;i++)slots[i]=0;}catch(Exception ignored){}}SegmentTree built=new SegmentTree(slots);SegmentTree prior=calendars.putIfAbsent(cacheKey,built);return prior==null?built:prior;}
 private static synchronized Map<String,Object> updateBooking(String id,String action){Map<String,Object>b=bookings.stream().filter(x->id.equals(x.get("id"))).findFirst().orElseThrow(()->new IllegalArgumentException("Booking not found"));String st=switch(action){case "approve"->"APPROVED";case "reject"->"REJECTED";case "cancel"->"CANCELLED";default->throw new IllegalArgumentException("Unsupported booking action");};b.put("status",st);calendars.remove(String.valueOf(b.get("venueId"))+"|"+Instant.parse(String.valueOf(b.get("start"))).atZone(ZoneId.of("Asia/Kolkata")).toLocalDate());saveAll();return b;}
 private static synchronized Map<String,Object> createEvent(Map<String,Object>in,Map<String,Object>actor){Map<String,Object>v=findVenue(String.valueOf(in.get("venueId")));if(!"APPROVED".equals(v.get("status"))||!String.valueOf(actor.get("id")).equals(v.get("ownerId")))throw new IllegalArgumentException("Events can only be published at your own approved venue.");String start=String.valueOf(in.get("startDatetime")),end=String.valueOf(in.get("endDatetime"));Instant startAt=Instant.parse(start),endAt=Instant.parse(end);if(!endAt.isAfter(startAt))throw new IllegalArgumentException("Event end must be after start");if(startAt.isBefore(Instant.now()))throw new IllegalArgumentException("Events must start in the future.");String title=String.valueOf(in.get("title")).trim();if(title.length()<3||title.length()>120)throw new IllegalArgumentException("Enter an event title between 3 and 120 characters.");String locality=String.valueOf(v.get("locality"));String eventDate=startAt.atZone(ZoneId.of("Asia/Kolkata")).toLocalDate().toString();eventDuplicateIndex.addNew(title,locality,eventDate);Map<String,Object>e=map("id","owner-event-"+UUID.randomUUID(),"title",title,"category",in.getOrDefault("category","Community event"),"venueName",v.get("name"),"locality",v.get("locality"),"lat",v.get("lat"),"lng",v.get("lng"),"startDatetime",start,"endDatetime",end,"priceText",in.getOrDefault("priceText","Check organiser"),"imageUrl",((List<?>)v.get("images")).get(0),"sourceUrl","","sourceType","OWNER","status","UPCOMING","fetchedAt",Instant.now().toString());events.add(0,e);saveAll();return e;}
 private static Object allocate(Map<String,Object>input){List<?>requests=(List<?>)input.getOrDefault("requests",List.of());List<Map<String,Object>>available=venues.stream().filter(v->"APPROVED".equals(v.get("status"))).toList();boolean[][]edges=new boolean[requests.size()][available.size()];for(int i=0;i<requests.size();i++){Map<?,?>r=(Map<?,?>)requests.get(i);for(int j=0;j<available.size();j++){var v=available.get(j);edges[i][j]=num(v,"capacity")>=((Number)(r.containsKey("guests")?r.get("guests"):1)).intValue()&&(r.get("category")==null||r.get("category").equals(v.get("category")))&&(r.get("locality")==null||r.get("locality").equals(v.get("locality")));}}int[]m=BipartiteMatching.maximumMatching(edges);List<Object>out=new ArrayList<>();for(int i=0;i<m.length;i++)out.add(map("requestIndex",i,"venue",m[i]<0?null:available.get(m[i]),"matched",m[i]>=0));return map("matches",out,"matchedCount",Arrays.stream(m).filter(x->x>=0).count());}
 private static Object cover(Map<String,Object>input){List<String>required=(List<String>)input.getOrDefault("requiredFacilities",List.of());List<Map<String,Object>>eligible=venues.stream().filter(v->"APPROVED".equals(v.get("status"))).toList();List<Set<String>>sets=new ArrayList<>();for(var v:eligible)sets.add(new HashSet<>((List<String>)v.get("amenities")));List<Integer>chosen=GreedySetCover.choose(sets,required);List<Object>selected=new ArrayList<>();for(int i:chosen)selected.add(eligible.get(i));Set<String>covered=new HashSet<>();for(int i:chosen)covered.addAll(sets.get(i));Set<String>missing=new HashSet<>(required);missing.removeAll(covered);return map("venues",selected,"coveredFacilities",covered,"uncoveredFacilities",missing,"algorithm","Greedy Set Cover approximation");}
 private static double num(Map<?,?>m,String k){Object o=m.get(k);return o instanceof Number n?n.doubleValue():0;}
 private static double distance(double a,double b,double c,double d){double p=Math.PI/180;double x=(c-a)*p,y=(d-b)*p;double h=Math.sin(x/2)*Math.sin(x/2)+Math.cos(a*p)*Math.cos(c*p)*Math.sin(y/2)*Math.sin(y/2);return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}
 private static Map<String,String>query(URI u){Map<String,String>m=new HashMap<>();String s=u.getRawQuery();if(s!=null)for(String part:s.split("&")){String[]p=part.split("=",2);m.put(URLDecoder.decode(p[0],StandardCharsets.UTF_8),p.length>1?URLDecoder.decode(p[1],StandardCharsets.UTF_8):"");}return m;}
 private static void send(HttpExchange x,int code,Object data)throws IOException{byte[]b=data==null?new byte[0]:Json.stringify(data).getBytes(StandardCharsets.UTF_8);String origin=x.getRequestHeaders().getFirst("Origin"),allowed=System.getenv().getOrDefault("DROP_CORS_ORIGIN","http://localhost:5173");if(origin!=null&&(allowed.equals("*")||allowed.equals(origin)))x.getResponseHeaders().set("Access-Control-Allow-Origin",origin);x.getResponseHeaders().set("Access-Control-Allow-Headers","Content-Type, Authorization");x.getResponseHeaders().set("Access-Control-Allow-Methods","GET,POST,PATCH,OPTIONS");if(code==204){x.sendResponseHeaders(204,-1);return;}x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.sendResponseHeaders(code,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}
